// Deterministic, explainable gate. The LLM scores; these rules decide.
const CRITERIA = ['clarity', 'testability', 'completeness', 'feasibility', 'business_value'];
const SENSITIVE_RISKS = ['data_privacy', 'compliance', 'legal'];
const PASS_MIN_SCORE = 3;
const PASS_AVG_SCORE = 3.8;
const REJECT_AVG_SCORE = 2.5;

const parseLlm = (json) => {
  let o = json.output ?? json.text ?? json;
  if (typeof o === 'string') {
    try { o = JSON.parse(o); } catch { return null; }
  }
  return o && typeof o === 'object' ? o : null;
};

const list = (x) => (Array.isArray(x) ? x.map(String).filter(Boolean) : []);
const originals = $('Normalize Requirement').all();

return $input.all().map((item, i) => {
  const src = originals[i]?.json ?? {};
  const llm = parseLlm(item.json);
  const issues = [];
  if (!llm) issues.push('unparseable_llm_output');
  const r = llm ?? {};
  if (r.requirement_id && r.requirement_id !== src.requirement_id) issues.push('requirement_id_mismatch');

  const scores = {};
  for (const c of CRITERIA) {
    const v = Number(r.scores?.[c]);
    if (Number.isInteger(v) && v >= 1 && v <= 5) scores[c] = v;
    else {
      scores[c] = null;
      issues.push(`invalid_score_${c}`);
    }
  }
  const valid = Object.values(scores).filter((v) => v !== null);
  const avg_score = valid.length ? Math.round((valid.reduce((s, v) => s + v, 0) / valid.length) * 100) / 100 : null;
  const ambiguities = list(r.ambiguities);
  const missing_information = list(r.missing_information);
  const risk_flags = list(r.risk_flags);
  const sensitive = risk_flags.filter((f) => SENSITIVE_RISKS.includes(f));

  const reasons = [];
  let gate;
  if (issues.length) {
    gate = 'REVIEW';
    reasons.push(`LLM output failed validation (${issues.join(', ')})`);
  } else if (avg_score < REJECT_AVG_SCORE) {
    gate = 'REJECT';
    reasons.push(`average score ${avg_score} < ${REJECT_AVG_SCORE}`);
  } else {
    if (sensitive.length) reasons.push(`sensitive risk: ${sensitive.join(', ')}`);
    if (Math.min(...valid) < PASS_MIN_SCORE) reasons.push(`at least one criterion below ${PASS_MIN_SCORE}`);
    if (avg_score < PASS_AVG_SCORE) reasons.push(`average score ${avg_score} < ${PASS_AVG_SCORE}`);
    if (ambiguities.length) reasons.push(`${ambiguities.length} ambiguous phrase(s)`);
    if (missing_information.length) reasons.push(`${missing_information.length} missing information item(s)`);
    gate = reasons.length ? 'REVIEW' : 'PASS';
    if (gate === 'PASS') reasons.push('all quality criteria met');
  }

  return {
    json: {
      ...src,
      gate,
      gate_reasons: reasons,
      scores,
      avg_score,
      ambiguities,
      missing_information,
      risk_flags,
      user_story: String(r.user_story ?? ''),
      acceptance_criteria: list(r.acceptance_criteria),
      clarifying_questions: list(r.clarifying_questions),
      validation_issues: issues,
      assessed_at: new Date().toISOString(),
    },
  };
});

