// All REVIEW items of one run go into ONE review request, so a single resume call carries every decision.
const items = $input.all().map((i) => i.json);
const lines = items.map((r) => [
  `• *${r.requirement_id}* ${r.title} (avg ${r.avg_score ?? 'n/a'})`,
  `   why: ${r.gate_reasons.join('; ')}`,
  `   ask requester: ${r.clarifying_questions.slice(0, 3).join(' | ') || '-'}`,
].join('\n'));
return [{
  json: {
    requirement_ids: items.map((r) => r.requirement_id),
    count: items.length,
    message: `${items.length} requirement(s) need a human decision:\n\n${lines.join('\n\n')}`,
    items,
  },
}];

// Map the reviewer's POST body back onto each requirement of the batch.
// Body: { "decisions": { "REQ-303": "reject", "REQ-304": "revise" }, "comment": "..." }
// Shortcut for a single decision for the whole batch: ?decision=approve
const ALLOWED = ['approve', 'revise', 'reject'];
const batch = $('Build Review Request').first().json;
const response = $input.first().json;
const body = response.body ?? {};
const query = response.query ?? {};
const decisions = body.decisions ?? {};

return batch.items.map((r) => {
  const decision = String(decisions[r.requirement_id] ?? query.decision ?? '').toLowerCase();
  return {
    json: {
      requirement_id: r.requirement_id,
      title: r.title,
      llm_gate: r.gate,
      llm_avg_score: r.avg_score,
      llm_risk_flags: r.risk_flags.join(', '),
      reviewer_decision: ALLOWED.includes(decision) ? decision : 'no_decision',
      reviewer_comment: String(body.comment ?? query.comment ?? ''),
      decided_at: new Date().toISOString(),
    },
  };
});

// REJECT: send it back to the requester with specific questions instead of a silent "no".
return $input.all().map(({ json: r }) => ({
  json: {
    requirement_id: r.requirement_id,
    to: r.requested_by,
    subject: `Clarification needed: ${r.title}`,
    body: [
      'Hello,',
      '',
      `thank you for submitting "${r.title}". Before we can assess it, could you help us with the following?`,
      '',
      ...r.clarifying_questions.map((q, i) => `${i + 1}. ${q}`),
      '',
      `Information we could not find yet: ${r.missing_information.join('; ') || '-'}`,
      '',
      'Best regards,',
      'Customer Innovation Team',
    ].join('\n'),
  },
}));
